    assert status == "REJECTED_BELOW_DEDUCTIBLE"

    status = decide("ACTIVE", 2000.0, 500.0, 400.0)
    assert status == "REJECTED_BELOW_DEDUCTIBLE"


def test_claim_rejected_over_limit():
    status = decide("ACTIVE", 2000.0, 500.0, 2100.0)
    assert status == "REJECTED_OVER_LIMIT"


def test_claim_rejected_policy_lapsed():
    status = decide("LAPSED", 2000.0, 500.0, 1500.0)
    assert status == "REJECTED_POLICY_LAPSED"

    status = decide("LAPSED", 2000.0, 500.0, 1000.0)
    assert status == "REJECTED_POLICY_LAPSED"


def test_payable_amount():
    assert payable(1000.0, 500.0) == 500.0
